@@ -130,4 +130,317 @@
       </aside>
     </div>
   </main>
   <script>
+    (() => {
+      const SIZE = 9;
+      const COLORS = ['green', 'red', 'blue'];
+      const NAMES = { green: 'verde', red: 'rojo', blue: 'azul' };
+      const boardEl = document.getElementById('board');
+      const scoreEl = document.getElementById('score');
+      const statusEl = document.getElementById('status');
+      const toastEl = document.getElementById('toast');
+      const collected = { green: 0, red: 0, blue: 0 };
+      let cells = [];
+      let board = [];
+      let selected = -1;
+      let score = 0;
+      let moves = 0;
+      let maxStreak = 0;
+      let round = 1;
+      let busy = false;
+      let toastTimer;
+      let hintTimer;
+
+      const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
+      const randomColor = () => COLORS[Math.floor(Math.random() * COLORS.length)];
+      const index = (row, col) => row * SIZE + col;
+
+      function findMatches(grid) {
+        const found = new Set();
+        for (let row = 0; row < SIZE; row++) {
+          let runStart = 0;
+          for (let col = 1; col <= SIZE; col++) {
+            const current = col < SIZE ? grid[index(row, col)] : null;
+            const previous = grid[index(row, col - 1)];
+            if (current !== previous || current === null) {
+              if (previous !== null && col - runStart >= 3) {
+                for (let k = runStart; k < col; k++) found.add(index(row, k));
+              }
+              runStart = col;
+            }
+          }
+        }
+        for (let col = 0; col < SIZE; col++) {
+          let runStart = 0;
+          for (let row = 1; row <= SIZE; row++) {
+            const current = row < SIZE ? grid[index(row, col)] : null;
+            const previous = grid[index(row - 1, col)];
+            if (current !== previous || current === null) {
+              if (previous !== null && row - runStart >= 3) {
+                for (let k = runStart; k < row; k++) found.add(index(k, col));
+              }
+              runStart = row;
+            }
+          }
+        }
+        return found;
+      }
+
+      function findMove(grid) {
+        for (let i = 0; i < grid.length; i++) {
+          if (grid[i] === null) continue;
+          const neighbors = [];
+          if (i % SIZE < SIZE - 1) neighbors.push(i + 1);
+          if (i + SIZE < grid.length) neighbors.push(i + SIZE);
+          for (const other of neighbors) {
+            if (grid[other] === null || grid[other] === grid[i]) continue;
+            [grid[i], grid[other]] = [grid[other], grid[i]];
+            const works = findMatches(grid).size > 0;
+            [grid[i], grid[other]] = [grid[other], grid[i]];
+            if (works) return [i, other];
+          }
+        }
+        return null;
+      }
+
+      function makeBoard() {
+        for (let attempt = 0; attempt < 100; attempt++) {
+          const grid = Array(SIZE * SIZE).fill(null);
+          for (let row = 0; row < SIZE; row++) {
+            for (let col = 0; col < SIZE; col++) {
+              const options = COLORS.filter(color => {
+                const horizontal = col >= 2 && grid[index(row, col - 1)] === color && grid[index(row, col - 2)] === color;
+                const vertical = row >= 2 && grid[index(row - 1, col)] === color && grid[index(row - 2, col)] === color;
+                return !horizontal && !vertical;
+              });
+              grid[index(row, col)] = options[Math.floor(Math.random() * options.length)];
+            }
+          }
+          if (findMove(grid)) return grid;
+        }
+        return Array.from({ length: SIZE * SIZE }, (_, i) => COLORS[(Math.floor(i / SIZE) + Math.floor(i % SIZE / 3)) % COLORS.length]);
+      }
+
+      function makeCells() {
+        boardEl.innerHTML = '';
+        cells = [];
+        for (let i = 0; i < SIZE * SIZE; i++) {
+          const cell = document.createElement('button');
+          cell.type = 'button';
+          cell.className = 'cell';
+          cell.setAttribute('role', 'gridcell');
+          cell.dataset.index = i;
+          cell.addEventListener('click', () => handleCell(i));
+          cell.addEventListener('keydown', event => handleKey(event, i));
+          boardEl.appendChild(cell);
+          cells.push(cell);
+        }
+      }
+
+      function render() {
+        for (let i = 0; i < board.length; i++) {
+          const color = board[i];
+          const cell = cells[i];
+          cell.classList.toggle('empty', color === null);
+          cell.classList.toggle('selected', selected === i);
+          cell.setAttribute('aria-label', color ? `${NAMES[color]} ${String.fromCharCode(65 + i % SIZE)}${Math.floor(i / SIZE) + 1}` : `vacía ${String.fromCharCode(65 + i % SIZE)}${Math.floor(i / SIZE) + 1}`);
+          cell.disabled = busy || color === null;
+          cell.innerHTML = color ? `<span class="orb ${color}" aria-hidden="true"></span>` : '';
+        }
+      }
+
+      function updateHud() {
+        scoreEl.textContent = String(score).padStart(4, '0');
+        document.getElementById('moves').textContent = moves;
+        document.getElementById('streak').textContent = `${maxStreak}×`;
+        let total = 0;
+        for (const color of COLORS) {
+          const amount = Math.min(3, collected[color]);
+          total += amount;
+          document.getElementById(`count-${color}`).textContent = amount;
+          document.getElementById(`goal-${color}`).classList.toggle('done', amount >= 3);
+        }
+        document.getElementById('progress').style.width = `${(total / 9) * 100}%`;
+        document.getElementById('round-tag').textContent = `RONDA ${String(round).padStart(2, '0')}`;
+      }
+
+      function showToast(message) {
+        clearTimeout(toastTimer);
+        toastEl.textContent = message;
+        toastEl.classList.add('show');
+        toastTimer = setTimeout(() => toastEl.classList.remove('show'), 1200);
+      }
+
+      function handleCell(i) {
+        if (busy || board[i] === null) return;
+        clearHints();
+        if (selected === i) {
+          selected = -1;
+          render();
+          return;
+        }
+        if (selected < 0 || !areNeighbors(selected, i)) {
+          selected = i;
+          statusEl.textContent = `Orbe ${String.fromCharCode(65 + i % SIZE)}${Math.floor(i / SIZE) + 1} seleccionada. Elige una contigua.`;
+          render();
+          return;
+        }
+        attemptSwap(selected, i);
+      }
+
+      function areNeighbors(a, b) {
+        return Math.abs(Math.floor(a / SIZE) - Math.floor(b / SIZE)) + Math.abs(a % SIZE - b % SIZE) === 1;
+      }
+
+      async function attemptSwap(a, b) {
+        selected = -1;
+        [board[a], board[b]] = [board[b], board[a]];
+        render();
+        await sleep(110);
+        if (!findMatches(board).size) {
+          [board[a], board[b]] = [board[b], board[a]];
+          render();
+          statusEl.textContent = 'Ese intercambio no forma una línea. Prueba otra combinación.';
+          showToast('¡Busca 3 del mismo color!');
+          return;
+        }
+        moves++;
+        updateHud();
+        await resolveMatches();
+      }
+
+      async function resolveMatches() {
+        busy = true;
+        let streak = 0;
+        let matchedAny = false;
+        while (true) {
+          const matches = findMatches(board);
+          if (!matches.size) break;
+          matchedAny = true;
+          streak++;
+          maxStreak = Math.max(maxStreak, streak);
+          const colorCounts = { green: 0, red: 0, blue: 0 };
+          for (const i of matches) {
+            colorCounts[board[i]]++;
+            cells[i].classList.add('clearing');
+          }
+          const total = matches.size;
+          score += total * 10 * streak;
+          for (const color of COLORS) collected[color] += colorCounts[color];
+          updateHud();
+          statusEl.textContent = streak > 1 ? `¡Racha ${streak}×! ${total} orbes recogidos.` : `${total} orbes recogidos. ¡Buen movimiento!`;
+          await sleep(210);
+          for (const i of matches) board[i] = null;
+          collapseColumns();
+          render();
+          await sleep(120);
+        }
+        busy = false;
+        render();
+        updateHud();
+        if (!matchedAny) return;
+        if (COLORS.every(color => collected[color] >= 3)) {
+          statusEl.textContent = '¡Colección completa! Preparando una nueva ronda…';
+          showToast('¡Colección completa! ✨');
+          setTimeout(() => startGame(true), 1900);
+        } else if (!findMove(board)) {
+          statusEl.textContent = 'No quedan combinaciones. Reordenando los orbes…';
+          setTimeout(() => reshuffle(), 650);
+        }
+      }
+
+      function collapseColumns() {
+        for (let col = 0; col < SIZE; col++) {
+          const remaining = [];
+          for (let row = SIZE - 1; row >= 0; row--) {
+            const color = board[index(row, col)];
+            if (color !== null) remaining.push(color);
+          }
+          for (let row = SIZE - 1; row >= 0; row--) {
+            board[index(row, col)] = remaining[SIZE - 1 - row] ?? null;
+          }
+        }
+      }
+
+      function reshuffle() {
+        const colors = board.filter(Boolean);
+        if (colors.length < 3) {
+          startGame(true);
+          return;
+        }
+        for (let attempt = 0; attempt < 300; attempt++) {
+          const shuffled = colors.slice().sort(() => Math.random() - 0.5);
+          let cursor = 0;
+          const candidate = board.map(cell => cell === null ? null : shuffled[cursor++]);
+          if (findMatches(candidate).size === 0 && findMove(candidate)) {
+            board = candidate;
+            statusEl.textContent = 'Los orbes se han reordenado. ¡Sigue jugando!';
+            render();
+            return;
+          }
+        }
+        // If a rare layout cannot be shuffled cleanly, refresh the board without resetting collection progress.
+        board = makeBoard();
+        statusEl.textContent = 'Nuevo tablero, misma colección. ¡A por los orbes que faltan!';
+        render();
+      }
+
+      function clearHints() {
+        clearTimeout(hintTimer);
+        cells.forEach(cell => cell.classList.remove('hint'));
+      }
+
+      function handleKey(event, i) {
+        if (event.key === 'ArrowRight' || event.key === 'ArrowLeft' || event.key === 'ArrowDown' || event.key === 'ArrowUp') {
+          event.preventDefault();
+          const delta = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : event.key === 'ArrowDown' ? SIZE : -SIZE;
+          const next = i + delta;
+          if (next >= 0 && next < SIZE * SIZE && (Math.abs(delta) === SIZE || Math.floor(next / SIZE) === Math.floor(i / SIZE))) cells[next].focus();
+        } else if (event.key === 'Enter' || event.key === ' ') {
+          event.preventDefault();
+          handleCell(i);
+        }
+      }
+
+      function startGame(nextRound = false) {
+        if (nextRound) round++;
+        clearTimeout(toastTimer);
+        clearTimeout(hintTimer);
+        busy = false;
+        selected = -1;
+        score = 0;
+        moves = 0;
+        maxStreak = 0;
+        collected.green = 0;
+        collected.red = 0;
+        collected.blue = 0;
+        board = makeBoard();
+        toastEl.classList.remove('show');
+        statusEl.textContent = 'Elige un orbe y cámbialo por uno contiguo.';
+        updateHud();
+        render();
+      }
+
+      document.getElementById('new-btn').addEventListener('click', () => {
+        startGame(true);
+        showToast('¡Nueva ronda!');
+      });
+      document.getElementById('hint-btn').addEventListener('click', () => {
+        if (busy) return;
+        clearHints();
+        const move = findMove(board);
+        if (!move) {
+          reshuffle();
+          return;
+        }
+        move.forEach(i => cells[i].classList.add('hint'));
+        statusEl.textContent = 'Pista: intercambia los dos orbes que parpadean.';
+        hintTimer = setTimeout(clearHints, 2200);
+      });
+
+      makeCells();
+      startGame();
+    })();
+  </script>
+</body>
+</html>

